            line_start = t.find('\n', start) + 1
            line = t[line_start:line_start+w]
            if len(line) == w:
                rows.append(line)
        if all(len(r) == w and all(c.isdigit() for c in row) for r in rows):
            grids[k] = [[int(c) for c in row] for row in rows]
    return grids

