from collections import deque

def find_horizontal_pairs(grid):
    pairs = []
    rows = len(grid)
    cols = len(grid[0]) if rows > 0 else 0

    visited = set()
    for r in range(rows):
        for c in range(cols):
            if grid[r][c] == 1 and (r, c) not in visited:
                # Start a chain of horizontally adjacent 1s
                chain = [(r, c)]
                visited.add((r, c))
                c2 = c + 1
                while c2 < cols and grid[r][c2] == 1:
                    chain.append((r, c2))
                    visited.add((r, c2))
                    c2 += 1

                # If chain length >= 2, we have at least one horizontal pair
                if len(chain) >= 2:
                    # Each adjacent pair in chain is a horizontal pair
                    for i in range(len(chain) - 1):
                        pairs.append(chain[i])
    return pairs

