def pairs_to_zero(grid):
    """Return set of row,col for pairs that should become 0"""
    zero_set = set()
    rows = len(grid)
    cols = len(grid[0])

    for r in range(rows):
        for c in range(cols - 1):
            if grid[r][c] == grid[r][c+1]:
                # Same-colored adjacent pair (excluding 0s)
                if is_pair_isolated_vertical(r, (c, c+1), grid):
                    zero_set.add((r, c))
                    zero_set.add((r, c+1))
    return zero_set

